use bevy::math::DVec3;
use bevy_als::extensions::control_rig_hierarchy::RigTransform;
use serde_json::{Value,json};
mod qualified{include!("../474/replay.rs");pub fn transform_input(v:&Value)->RigTransform{transform(v)}pub fn math(v:&Value)->RigTransform{model_transform(v)}}
fn source_cm(v:&Value)->RigTransform{let mut r=qualified::transform_input(v);let t=&v["translation"];r.translation=DVec3::new(t["x"].as_f64().unwrap(),t["z"].as_f64().unwrap(),t["y"].as_f64().unwrap());r}
fn main(){let root=std::path::Path::new("docs/audit/bf144/475");let label=std::env::args().nth(1).unwrap();let data:Value=serde_json::from_slice(&std::fs::read(root.join("inputs.json")).unwrap()).unwrap();let mut common=Vec::new();let mut actual=Vec::new();
 for row in data["source"].as_array().unwrap(){let a=&row["global_transform"];let b=&row["parent_global"];let meters=qualified::transform_input(a).relative(qualified::transform_input(b));let centimeters=meters;assert_eq!(meters,qualified::math(&row["qualified_models"]["0"]["stages"]),"Current public meter method exact");assert_eq!(centimeters,qualified::math(&row["qualified_models"]["8"]["stages"]),"Independent public centimeter method exact");assert_eq!(meters.rotation,centimeters.rotation);assert_eq!(meters.scale,centimeters.scale);
 let dirty=row["local_dirty"].as_bool().unwrap();let native=qualified::transform_input(&row["native_local"]);let held=qualified::transform_input(&row["before_local"]);let current_m=if dirty{meters}else{held};let current_cm=if dirty{centimeters}else{held};let source_m=qualified::math(&row["qualified_models"]["7"]["result"]);let source_cm=qualified::math(&row["qualified_models"]["15"]["result"]);assert_eq!(source_cm,native);common.push(json!({"dataset":row["dataset"],"case":row["case"],"query":row["query"],"foot":row["foot"],"local_dirty":dirty,"current_meter":current_m,"current_centimeter":current_cm,"source_meter":source_m,"source_centimeter":source_cm,"native":native}));}
 for row in data["actual"].as_array().unwrap(){let a:RigTransform=serde_json::from_value(row["global_transform"].clone()).unwrap();let b:RigTransform=serde_json::from_value(row["parent_global"].clone()).unwrap();let meter=a.relative(b);let expected:RigTransform=serde_json::from_value(row["expected_local"].clone()).unwrap();assert_eq!(meter,expected);let(mut ac,mut bc)=(a,b);ac.translation*=100.;bc.translation*=100.;let mut centimeter=ac.relative(bc);centimeter.translation*=0.01;assert_eq!(centimeter,serde_json::from_value::<RigTransform>(row["qualified_models"]["0:8"]["result"].clone()).unwrap());assert_eq!(meter.rotation,centimeter.rotation);assert_eq!(meter.scale,centimeter.scale);actual.push(json!({"mode":row["mode"],"query":row["query"],"foot":row["foot"],"current_meter":meter,"current_centimeter":centimeter,"source_meter":row["qualified_models"]["0:7"]["result"],"source_centimeter":row["qualified_models"]["0:15"]["result"],"native":row["qualified_models"]["0:0"]["native"]}));}
 assert_eq!(common.len(),696);assert_eq!(actual.len(),1272);std::fs::write(root.join(format!("replay-{label}.json")),serde_json::to_vec(&json!({"gate":"INDEPENDENT_PUBLIC_RELATIVE_CM_M_DOUBLE_CONTROLS_AND_QUALIFIED_SOURCE_UNIT_PHASE","common":common,"actual":actual,"source_unit_phase_still_not_a_float32_cast":true})).unwrap()).unwrap();println!("Qualified696 same-source and1272 actual public cm/m double relative calls without changing Q/S/algorithm");}
